package com.example.emitterapp.ui.rc_screen
import android.annotation.SuppressLint import android.util.Log import androidx.compose.foundation.layout.Arrangement import androidx.compose.foundation.layout.Box import androidx.compose.foundation.layout.BoxWithConstraints import androidx.compose.foundation.layout.Column import androidx.compose.foundation.layout.Row import androidx.compose.foundation.layout.fillMaxHeight import androidx.compose.foundation.layout.fillMaxSize import androidx.compose.foundation.layout.offset import androidx.compose.foundation.layout.padding import androidx.compose.foundation.layout.size import androidx.compose.runtime.Composable import androidx.compose.runtime.remember import androidx.compose.ui.Alignment import androidx.compose.ui.Modifier import androidx.compose.ui.graphics.Color import androidx.compose.ui.platform.LocalDensity import androidx.compose.ui.tooling.preview.Preview import androidx.compose.ui.unit.dp import com.example.emitterapp.ui.rc_screen.components.ButtonSide import com.example.emitterapp.ui.rc_screen.components.JoystickMode import com.example.emitterapp.ui.rc_screen.components.Joystick_RC3D import com.example.emitterapp.ui.rc_screen.components.Knob3D import com.example.emitterapp.ui.rc_screen.components.LedIndicator import com.example.emitterapp.ui.rc_screen.components.SevenSegmentedPanel import com.example.emitterapp.ui.rc_screen.components.Switch3DButton import com.example.emitterapp.ui.rc_screen.components.AnalogIndicator import com.example.emitterapp.ui.rc_screen.components.BatteryStatus import kotlin.math.cos import kotlin.math.sin
@SuppressLint("UnusedBoxWithConstraintsScope") @Composable fun ControllerSide( modifier: Modifier = Modifier, side: ButtonSide, mode: JoystickMode, onMove: (x: Float, y: Float) -> Unit, switchStates: List<Boolean>, onSwitchStateChange: (index: Int, inOn: Boolean) -> Unit, knobValue: Float, onKnobValueChange: (Float) -> Unit, panelNumber: Int, panelOn: Boolean, panelColor: Color, panelTitle: String, topExtraContent: (@Composable (modifier: Modifier) -> Unit)? = null, aspectRatio: Float, ledValues: Byte = 0x00, onTopPress: () -> Unit, onBottomPress: () -> Unit, ) { val ledStates = remember(ledValues) { if (side == ButtonSide.LEFT) { // Use the first 4 bits (0, 1, 2, 3) for the Left side listOf( (ledValues.toInt() and 0b00000001) != 0, // Check bit 0 (ledValues.toInt() and 0b00000010) != 0, // Check bit 1 (ledValues.toInt() and 0b00000100) != 0, // Check bit 2 (ledValues.toInt() and 0b00001000) != 0 // Check bit 3 ) } else { // Side.RIGHT // Use the next 4 bits (4, 5, 6, 7) for the Right side listOf( (ledValues.toInt() and 0b00010000) != 0, // Check bit 4 (ledValues.toInt() and 0b00100000) != 0, // Check bit 5 (ledValues.toInt() and 0b01000000) != 0, // Check bit 6 (ledValues.toInt() and 0b10000000) != 0 // Check bit 7 ) } } BoxWithConstraints( modifier = modifier.fillMaxHeight(), contentAlignment = Alignment.BottomCenter ) { val density = LocalDensity.current val mmInDp = density.density * 160f / 25.4f Log.d("DeviceMetrics", "Width: ${maxWidth}, Height: ${maxHeight}, DPI: $mmInDp, Aspect Ratio: $aspectRatio") val targetMm = if (aspectRatio > 2.0f) 30f else 100f val maxSize = if (aspectRatio > 2.0f) 200.dp else 300.dp val joystickSize = (targetMm * mmInDp).dp.coerceIn(100.dp, maxSize) val switchMultiplier = if (aspectRatio > 2.0f) 0.3f else 0.5f val knobSize = joystickSize * 0.35f val switchSize = joystickSize * switchMultiplier
val extraContentSizeBattery = joystickSize * 0.3f val extraContentSizeAnalogIndicator = joystickSize * 0.3f
val panelWidth = joystickSize * 0.6f Box( modifier = Modifier .size(joystickSize), contentAlignment = Alignment.BottomEnd, ) { ButtonColumn( modifier = Modifier .size(joystickSize * 0.4f) .align( if (side == ButtonSide.RIGHT) Alignment.BottomStart else Alignment.BottomEnd ), onTopPress = onTopPress, onBottomPress = onBottomPress, side = side, isWideScreen = false, buttonSize = joystickSize * 0.2f, ) Joystick_RC3D( modifier = Modifier .offset(x = if (side == ButtonSide.RIGHT) (-joystickSize * -0.02f) else (joystickSize * -0.02f), y = (-joystickSize * 0.1f)) .fillMaxSize(), mode = mode, onMove = onMove )
val knobAngle = if (side == ButtonSide.RIGHT) 50f else 130f val radius = joystickSize * 0.35f val knobRadius = joystickSize * 0.45f
val switchPositions = if (side == ButtonSide.RIGHT) { listOf( Pair(0.dp, -50.dp), Pair(40.dp, -30.dp), Pair(80.dp, -10.dp) ) } else { listOf( Pair(0.dp, -50.dp), Pair(-40.dp, -30.dp), Pair(-80.dp, -10.dp) ) }
switchPositions.forEachIndexed { index, (xOffset, yOffset) -> Box( modifier = Modifier .size(switchSize) .align(Alignment.TopCenter) .offset(x = if(side == ButtonSide.RIGHT) xOffset - (joystickSize * 0.05f) else xOffset + (joystickSize * 0.05f), y = yOffset- (joystickSize * 0.2f)) ) { if (switchStates.size > index) { Switch3DButton( isOn = switchStates[index], onStateChange = { newState -> onSwitchStateChange(index, newState) } ) } } }
val knobAngleRadians = Math.toRadians(knobAngle.toDouble()) val knobXOffset = (knobRadius.value * cos(knobAngleRadians)).dp val knobYOffset = (knobRadius.value * sin(knobAngleRadians)).dp Box( modifier = Modifier .size(knobSize) .align(Alignment.Center) .offset(x = -knobXOffset, y = -knobYOffset - joystickSize * 0.25f) ) { Knob3D( value = knobValue, onValueChange = onKnobValueChange ) } } Row( modifier = Modifier .align(Alignment.TopCenter), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically ) { if (side == ButtonSide.RIGHT) { Column(verticalArrangement = Arrangement.spacedBy(8.dp)) { ledStates.forEach { isOn -> LedIndicator(isOn = isOn, size = 14.dp) } } SevenSegmentedPanel( width = panelWidth, value = panelNumber / 10f, on = panelOn, onColor = panelColor, title = panelTitle ) topExtraContent?.invoke(Modifier.size(extraContentSizeBattery))
} else { topExtraContent?.invoke(Modifier.size(extraContentSizeAnalogIndicator)) SevenSegmentedPanel( // modifier = Modifier.weight(1f), width = panelWidth, value = panelNumber / 10f, on = panelOn, onColor = panelColor, title = panelTitle ) Column(verticalArrangement = Arrangement.spacedBy(8.dp)) { ledStates.forEach { isOn -> LedIndicator(isOn = isOn, size = 14.dp) } } } } } }
@Preview(showBackground = true, name = "ControllerSide Left") @Composable fun ControllerSideLeftPreview() { val fakeViewModel = FakeBluetoothViewModel() ControllerSide( side = ButtonSide.LEFT, mode = JoystickMode.Spring(), onMove = { _, _ -> }, switchStates = listOf(true, false, true), onSwitchStateChange = { _, _ -> }, knobValue = 0.5f, onKnobValueChange = {}, panelNumber = 1234, panelOn = true, panelColor = Color.Red, panelTitle = "RPM", topExtraContent = { modifier -> AnalogIndicator( modifier = modifier, value = 75, title = "Analog" ) }, aspectRatio = 2.2f, ledValues = 0x0F.toByte(), onTopPress = {}, onBottomPress = {} ) }
@Preview(showBackground = true, name = "ControllerSide Right") @Composable fun ControllerSideRightPreview() { val fakeViewModel = FakeBluetoothViewModel() ControllerSide( side = ButtonSide.RIGHT, mode = JoystickMode.Spring(), onMove = { _, _ -> }, switchStates = listOf(false, true, false), onSwitchStateChange = { _, _ -> }, knobValue = 0.7f, onKnobValueChange = {}, panelNumber = 5678, panelOn = true, panelColor = Color.Green, panelTitle = "RPM", topExtraContent = { modifier -> BatteryStatus( level = 98, modifier = modifier, title = "Battery" ) }, aspectRatio = 2.2f, ledValues = 0xF0.toByte(), onTopPress = {}, onBottomPress = {} ) }

