@Preview(showBackground = true, device = "spec:width=1024dp,height=600dp,dpi=160", name = "RcScreen Small Tablet Landscape")
@Composable
fun RcScreenPreviewSmallTablet() {
    EmitterAppTheme {
        val fakeViewModel = FakeBluetoothViewModel()
        RcScreen(
